UPDATE battlesnakes b SET engine_region = i.engine_region FROM imported_snakes i WHERE i.materialized_battlesnake_id = b.battlesnake_id AND b.engine_region <> i.engine_region;

UPDATE battlesnakes SET engine_region = 'europe-west4' WHERE battlesnake_id = ANY('{0c041986-aecb-4dc2-9e1e-3e03fd629e04,12e234c6-71c9-428d-bc5e-8da9ec35c3c1,1a137d8a-ff38-49fb-b73e-58579f47e47c,4ea818f5-10ac-4634-8cec-f4402c718d76,8207d093-5219-4232-8b93-46bcda656676,91f75a91-3a36-482c-a663-48a1e6cf3b0b,d4406468-7c1c-41ca-9cf5-03fc9e7415b5,d78c0483-34d0-41f9-89ff-efc470d7cfdb}'::uuid[]) AND engine_region <> 'europe-west4';

